SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM attendance_policy_scoped_version version
    JOIN attendance_policy_scope scope ON scope.scope_id = version.scope_id
    JOIN attendance_policy_template template
      ON template.policy_template_id = scope.policy_template_id
    WHERE version.scoped_version_id = #{policyVersionId}
      AND scope.legal_entity_id = #{legalEntityId}
      AND template.template_code = #{policyKind}
      AND version.effective_from <= #{effectiveFrom}
      AND (version.effective_to IS NULL
           OR (#{effectiveTo} IS NOT NULL
               AND version.effective_to >= #{effectiveTo}))
      AND 
) THEN TRUE ELSE FALSE END

SELECT snapshot_digest
FROM attendance_policy_scoped_version
WHERE scoped_version_id = #{policyVersionId}

SELECT parameters_json
FROM attendance_policy_scoped_version
WHERE scoped_version_id = #{policyVersionId}

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM attendance_policy_binding_family family
    WHERE family.policy_kind = #{policyKind}
      AND family.attendance_group_id = #{groupId}
      AND (#{excludeBindingId} IS NULL
           OR family.binding_family_id <> #{excludeBindingId})
) THEN TRUE ELSE FALSE END

SELECT 
FROM 
JOIN attendance_policy_scoped_version version
  ON version.scoped_version_id =
     revision.attendance_policy_scoped_version_id
WHERE family.attendance_group_id = #{groupId}
  AND revision.attendance_group_revision_id = #{groupRevisionId}
  AND revision.effective_from <= #{businessDate}
  AND ( IS NULL
       OR 
            > #{businessDate})
  AND revision.created_at <= #{knowledgeAsOf}
  AND version.effective_from <= #{businessDate}
  AND (version.effective_to IS NULL
       OR version.effective_to > #{businessDate})
  AND NOT EXISTS (
      SELECT 1 FROM attendance_policy_binding_revision newer
      WHERE newer.binding_family_id = revision.binding_family_id
        AND newer.revision_number > revision.revision_number
        AND newer.effective_from <= #{businessDate}
        AND newer.created_at <= #{knowledgeAsOf}
  )
  AND EXISTS (
      SELECT 1 FROM attendance_policy_lifecycle_event publication
      WHERE publication.scope_id = version.scope_id
        AND publication.scoped_version_id = version.scoped_version_id
        AND publication.action = 'PUBLISHED'
        AND publication.business_effective_from <= #{businessDate}
        AND publication.recorded_at <= #{knowledgeAsOf}
        AND NOT EXISTS (
            SELECT 1 FROM attendance_policy_lifecycle_event later
            WHERE later.scope_id = publication.scope_id
              AND later.event_sequence > publication.event_sequence
              AND later.business_effective_from <= #{businessDate}
              AND later.recorded_at <= #{knowledgeAsOf}
              AND later.action IN ('DEACTIVATE_SCHEDULED', 'ROLLED_BACK')
        )
  )
ORDER BY family.policy_kind, family.binding_family_id
